export const APP_HTML = "<!doctype html>\n<html lang=\"zh-Hant\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1, viewport-fit=cover\">\n<title>MRL_AI OS · Particle Universe</title>\n<link rel=\"icon\" href=\"data:image/svg+xml,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 32 32'><text y='26' font-size='28'>✦</text></svg>\">\n<!--\n  MRL_AI OS — 產品級入口 (MRL_Product_Entry_UI)\n  origin_signature: MrLiouWord\n  對應工程交代：Issue #25 產品級首頁 / #26 大輸入框 / #27 不用工程測試頁或裸JSON /\n                #28 內部 MRL_ 命名+外部商業名映射 / #29 新會話・歷史會話・任務狀態\n  權位：本頁為對外門面 (Adapter)；母體本體在 DL580 / MotherAssembly。\n        接不通後端時，誠實顯示「需母體後端」，不偽造成功。\n-->\n<style>\n:root{\n  --bg:#0b0f0d; --panel:#0f1512; --panel2:#121a16; --line:#1d2a22;\n  --ink:#e7f0ea; --dim:#8aa294; --acc:#27d07a; --acc2:#1f9d63;\n  --danger:#ff6b6b; --warn:#ffcc66; --chip:#15201a; --radius:14px;\n}\n*{box-sizing:border-box}\nhtml,body{margin:0;height:100%}\nbody{background:var(--bg);color:var(--ink);font:15px/1.55 -apple-system,\"PingFang TC\",\"Noto Sans TC\",Segoe UI,Roboto,sans-serif;-webkit-font-smoothing:antialiased}\nbutton{font:inherit;cursor:pointer;color:inherit}\na{color:var(--acc)}\n.hide{display:none!important}\n\n/* ── Login ── */\n#login{position:fixed;inset:0;display:flex;align-items:center;justify-content:center;background:radial-gradient(1200px 600px at 50% -10%,#10241a 0%,var(--bg) 60%);padding:24px;z-index:50}\n.lcard{width:100%;max-width:420px;background:var(--panel);border:1px solid var(--line);border-radius:20px;padding:28px;box-shadow:0 24px 60px rgba(0,0,0,.5)}\n.brandbig{display:flex;flex-direction:column;align-items:center;gap:10px;margin-bottom:18px}\n.logo{width:58px;height:58px;border-radius:16px;background:linear-gradient(135deg,#2bd47e,#168a9e);display:grid;place-items:center;font-size:26px;box-shadow:0 8px 24px rgba(43,212,126,.35)}\n.lcard h1{margin:2px 0 0;font-size:22px;letter-spacing:.5px}\n.lcard .sub{color:var(--dim);font-size:13px}\n.field{margin:14px 0}\n.field label{display:block;font-size:12px;color:var(--dim);margin-bottom:6px}\n.field input{width:100%;padding:12px 14px;background:var(--panel2);border:1px solid var(--line);border-radius:10px;color:var(--ink);font:inherit}\n.btn{width:100%;padding:12px 14px;border:0;border-radius:10px;background:var(--acc);color:#04150c;font-weight:700}\n.btn.ghost{background:transparent;border:1px solid var(--line);color:var(--ink);font-weight:500}\n.btn.sso{display:flex;align-items:center;justify-content:center;gap:10px;margin-top:10px}\n.divider{display:flex;align-items:center;gap:10px;color:var(--dim);font-size:12px;margin:16px 0}\n.divider::before,.divider::after{content:\"\";height:1px;background:var(--line);flex:1}\n.note{font-size:11px;color:var(--dim);text-align:center;margin-top:14px}\n.pending{font-size:10px;color:var(--warn);border:1px solid #3a3320;background:#1a1710;border-radius:6px;padding:1px 6px;margin-left:6px}\n\n/* ── App shell ── */\n#app{display:grid;grid-template-columns:264px 1fr;height:100%}\naside{background:var(--panel);border-right:1px solid var(--line);display:flex;flex-direction:column;min-height:0}\n.brand{display:flex;align-items:center;gap:10px;padding:16px 16px 12px}\n.brand .logo{width:34px;height:34px;border-radius:10px;font-size:16px}\n.brand b{font-size:15px}\n.brand small{display:block;color:var(--dim);font-size:11px;font-weight:400}\n.newbtn{margin:4px 12px 8px;padding:10px;border:1px solid var(--line);border-radius:10px;background:var(--panel2);display:flex;align-items:center;gap:8px;color:var(--ink);font-weight:600}\n.newbtn:hover{border-color:var(--acc2)}\n.navwrap{overflow:auto;flex:1;min-height:0;padding:4px 8px 8px}\n.navsec{color:var(--dim);font-size:10px;letter-spacing:1px;text-transform:uppercase;padding:12px 10px 4px}\n.nav{display:flex;align-items:center;gap:10px;padding:9px 10px;border-radius:9px;color:var(--ink);width:100%;border:0;background:transparent;text-align:left}\n.nav .ic{width:22px;height:22px;border-radius:7px;display:grid;place-items:center;font-size:13px;background:var(--chip);flex:none}\n.nav:hover{background:var(--panel2)}\n.nav.on{background:linear-gradient(90deg,rgba(39,208,122,.16),rgba(39,208,122,.04));color:#fff}\n.nav.on .ic{background:var(--acc);color:#04150c}\n.nav small{display:block;color:var(--dim);font-size:10px}\n.foot{border-top:1px solid var(--line);padding:10px 14px;color:var(--dim);font-size:11px;display:flex;justify-content:space-between;align-items:center}\n\nmain{display:flex;flex-direction:column;min-width:0;min-height:0}\n.topbar{display:flex;align-items:center;gap:12px;padding:12px 18px;border-bottom:1px solid var(--line);background:linear-gradient(180deg,var(--panel),transparent)}\n.topbar .title{font-weight:700}\n.topbar .tag{font-size:11px;color:var(--dim);border:1px solid var(--line);border-radius:999px;padding:2px 9px}\n.dot{width:8px;height:8px;border-radius:50%;background:var(--acc);box-shadow:0 0 0 3px rgba(39,208,122,.18)}\n.dot.off{background:var(--warn);box-shadow:0 0 0 3px rgba(255,204,102,.16)}\n.spacer{flex:1}\n.content{flex:1;overflow:auto;min-height:0}\n.view{display:none;height:100%}\n.view.on{display:block}\n\n/* Home */\n.home{max-width:860px;margin:0 auto;padding:8vh 22px 40px;text-align:center}\n.home h2{font-size:30px;margin:0 0 6px}\n.home .lead{color:var(--dim);margin-bottom:26px}\n.composer{background:var(--panel);border:1px solid var(--line);border-radius:18px;padding:14px;text-align:left;box-shadow:0 16px 40px rgba(0,0,0,.35)}\n.composer textarea{width:100%;border:0;background:transparent;color:var(--ink);font:16px/1.5 inherit;resize:none;outline:none;min-height:76px}\n.composer .row{display:flex;align-items:center;gap:8px;margin-top:8px}\n.composer select{background:var(--panel2);border:1px solid var(--line);border-radius:8px;color:var(--ink);padding:7px 9px;font:inherit}\n.send{margin-left:auto;background:var(--acc);color:#04150c;border:0;border-radius:10px;padding:9px 18px;font-weight:700}\n.cards{display:grid;grid-template-columns:repeat(auto-fill,minmax(150px,1fr));gap:10px;margin-top:18px}\n.qcard{background:var(--panel);border:1px solid var(--line);border-radius:12px;padding:14px;text-align:left;display:flex;gap:10px;align-items:center}\n.qcard:hover{border-color:var(--acc2);background:var(--panel2)}\n.qcard .ic{width:30px;height:30px;border-radius:9px;background:var(--chip);display:grid;place-items:center}\n\n/* Chat */\n.chatwrap{display:flex;flex-direction:column;height:100%}\n.msgs{flex:1;overflow:auto;padding:22px;max-width:900px;margin:0 auto;width:100%}\n.msg{display:flex;gap:12px;margin-bottom:18px}\n.msg .av{width:30px;height:30px;border-radius:9px;flex:none;display:grid;place-items:center;background:var(--chip);font-size:14px}\n.msg.me .av{background:#21304a}\n.msg.ai .av{background:var(--acc);color:#04150c}\n.bub{background:var(--panel);border:1px solid var(--line);border-radius:12px;padding:11px 14px;white-space:pre-wrap;word-break:break-word;max-width:100%}\n.msg.me .bub{background:var(--panel2)}\n.status{font-size:11px;color:var(--dim);margin:2px 0 0}\n.status .s{display:inline-block;padding:1px 8px;border-radius:999px;border:1px solid var(--line)}\n.s.QUEUED{color:var(--dim)} .s.RUNNING{color:var(--warn);border-color:#3a3320}\n.s.DONE{color:var(--acc);border-color:var(--acc2)} .s.FAILED{color:var(--danger);border-color:#4a2222}\n.composer.bottom{max-width:900px;margin:0 auto;width:100%;border-radius:0;border-left:0;border-right:0;border-bottom:0;background:transparent;box-shadow:none;padding:14px 22px 18px}\n\n/* Generic tool panel */\n.panel{max-width:880px;margin:0 auto;padding:30px 22px}\n.panel h2{margin:0 0 4px}\n.panel .lead{color:var(--dim);margin-bottom:18px}\n.box{background:var(--panel);border:1px solid var(--line);border-radius:12px;padding:16px;margin-bottom:14px}\n.kv{display:flex;gap:8px;flex-wrap:wrap}\n.act{background:var(--panel2);border:1px solid var(--line);border-radius:9px;padding:8px 14px;font-weight:600}\n.act.primary{background:var(--acc);color:#04150c;border:0}\npre{background:#070b09;border:1px solid var(--line);border-radius:10px;padding:12px;overflow:auto;font:12px/1.5 ui-monospace,SFMono-Regular,Menlo,monospace;color:#cfe9da;margin:10px 0 0}\n.banner{display:flex;gap:10px;align-items:flex-start;border:1px solid #3a3320;background:#15110a;border-radius:10px;padding:10px 12px;color:var(--warn);font-size:13px}\ntable{width:100%;border-collapse:collapse;font-size:13px}\ntd,th{border-bottom:1px solid var(--line);padding:8px 6px;text-align:left}\n.sesslist{padding:4px 8px}\n.sess{display:flex;align-items:center;gap:8px;padding:8px 10px;border-radius:9px;color:var(--ink);width:100%;border:0;background:transparent;text-align:left;font-size:13px}\n.sess:hover{background:var(--panel2)} .sess.on{background:var(--panel2)}\n.sess .t{flex:1;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\n.sess .x{opacity:0;color:var(--dim)} .sess:hover .x{opacity:1}\n#menuBtn{display:none}\n#scrim{display:none}\n@media(max-width:820px){\n  #app{grid-template-columns:1fr}\n  aside{position:fixed;top:0;bottom:0;left:0;width:82%;max-width:300px;z-index:30;transform:translateX(-100%);transition:transform .22s ease}\n  aside.open{transform:none;box-shadow:0 0 60px rgba(0,0,0,.65)}\n  #menuBtn{display:inline-block}\n  #scrim.on{display:block;position:fixed;inset:0;background:rgba(0,0,0,.5);z-index:25}\n  .home{padding:6vh 16px 40px}.home h2{font-size:24px}\n}\n</style>\n</head>\n<body>\n\n<!-- ───────────── Login (Issue #25 入口 / P1-1 帳號待接後端) ───────────── -->\n<div id=\"login\">\n  <div class=\"lcard\">\n    <div class=\"brandbig\">\n      <div class=\"logo\">✦</div>\n      <h1>MRL_AI OS</h1>\n      <div class=\"sub\">智能作業系統平台 · Particle Universe</div>\n    </div>\n    <div class=\"field\">\n      <label>Email 地址</label>\n      <input id=\"email\" type=\"email\" placeholder=\"your@email.com\" autocomplete=\"email\">\n    </div>\n    <button class=\"btn\" id=\"magic\">發送登入連結<span class=\"pending\">待接後端</span></button>\n    <div class=\"divider\">或</div>\n    <button class=\"btn sso ghost\" data-sso=\"Google\">使用 Google 登入<span class=\"pending\">待接後端</span></button>\n    <button class=\"btn sso ghost\" data-sso=\"Apple\">使用 Apple 登入<span class=\"pending\">待接後端</span></button>\n    <div class=\"divider\">先看產品</div>\n    <button class=\"btn\" id=\"guest\">以訪客進入 MRL_AI OS</button>\n    <div class=\"note\">origin_signature = MrLiouWord ｜ 登入即表示同意服務條款與隱私政策<br>\n      SSO / Email 登入需 MRL_Auth 後端 (Issue #11 · P1-1)，目前為前端入口。</div>\n  </div>\n</div>\n\n<!-- ───────────── App shell ───────────── -->\n<div id=\"app\" class=\"hide\">\n  <aside id=\"aside\">\n    <div class=\"brand\">\n      <div class=\"logo\">✦</div>\n      <div><b>MRL_AI</b><small>Particle Universe</small></div>\n    </div>\n    <button class=\"newbtn\" id=\"newSess\">＋ 新會話</button>\n    <div class=\"navwrap\">\n      <div class=\"navsec\">會話 / Sessions</div>\n      <div class=\"sesslist\" id=\"sesslist\"></div>\n      <div class=\"navsec\">工具 / Tools</div>\n      <div id=\"navtools\"></div>\n      <div class=\"navsec\">母體 / Core</div>\n      <div id=\"navcore\"></div>\n    </div>\n    <div class=\"foot\"><span>MrLiouWord</span><span id=\"footver\">v1.7</span></div>\n  </aside>\n\n  <main>\n    <div class=\"topbar\">\n      <button class=\"act\" id=\"menuBtn\" style=\"padding:6px 12px\">☰ 工具</button>\n      <span class=\"dot\" id=\"coreDot\"></span>\n      <span class=\"title\" id=\"topTitle\">MRL_AI</span>\n      <span class=\"tag\">權位區分模式</span>\n      <span class=\"tag\" id=\"engineTag\">engine: 偵測中…</span>\n      <div class=\"spacer\"></div>\n      <span class=\"tag\">canonical: 中文</span>\n    </div>\n    <div class=\"content\" id=\"content\"></div>\n  </main>\n  <div id=\"scrim\"></div>\n</div>\n\n<script>\nconst ORIGIN_SIGNATURE=\"MrLiouWord\";\nconst $=(s,r=document)=>r.querySelector(s);\n\n/* ── Issue #28：內部 MRL_ 命名 → 外部商業顯示名映射 ── */\nconst TOOLS=[\n  {id:\"MRL_Dialogue\",     name:\"AI 對話\",        ic:\"🤖\", sec:\"tool\", api:\"/api/chat\", home:true},\n  {id:\"MRL_VideoGen\",     name:\"影片生成器\",      ic:\"🎬\", sec:\"tool\"},\n  {id:\"MRL_SkillCreator\", name:\"技能創作者\",      ic:\"✨\", sec:\"tool\"},\n  {id:\"MRL_Config\",       name:\"MRL Config\",     ic:\"⚙️\", sec:\"tool\"},\n  {id:\"MRL_ASIReport\",    name:\"ASI 分析報告\",    ic:\"🧪\", sec:\"tool\"},\n  {id:\"MRL_ImageStudio\",  name:\"圖像工坊\",        ic:\"🖼️\", sec:\"tool\"},\n  {id:\"MRL_AudioGen\",     name:\"生成音頻\",        ic:\"🎙️\", sec:\"tool\"},\n  {id:\"MRL_Slides\",       name:\"製作投影片\",      ic:\"📊\", sec:\"tool\"},\n  {id:\"MRL_Sheets\",       name:\"建立電子表格\",    ic:\"📗\", sec:\"tool\"},\n  {id:\"MRL_WideResearch\", name:\"Wide Research\",  ic:\"🌐\", sec:\"tool\"},\n  {id:\"MRL_Scheduler\",    name:\"排程任務\",        ic:\"🗓️\", sec:\"tool\"},\n  {id:\"MRL_Playbook\",     name:\"Playbook\",       ic:\"📘\", sec:\"tool\"},\n  {id:\"MRL_Database\",     name:\"資料庫\",          ic:\"🗄️\", sec:\"tool\"},\n  {id:\"MRL_Monitor\",      name:\"即時監控\",        ic:\"📈\", sec:\"core\", api:\"/api/monitor\"},\n  {id:\"MRL_Console\",      name:\"母體控制台\",      ic:\"🛰️\", sec:\"core\", api:\"/api/mother/status\"},\n  {id:\"MRL_QuantumTopology\", name:\"MRL_QuantumTopology\", ic:\"🧬\", sec:\"core\"},\n  {id:\"MRL_SuperComputer\",   name:\"MRL_SUPERCOMPUTER\",   ic:\"🖥️\", sec:\"core\"},\n  {id:\"MRL_Settings\",     name:\"設定\",            ic:\"🔧\", sec:\"core\"},\n];\nconst HOME_CARDS=[\n  {t:\"製作簡報\", ic:\"📊\", tool:\"MRL_Slides\", prompt:\"幫我製作一份簡報：\"},\n  {t:\"建立網站\", ic:\"🌐\", tool:\"MRL_SkillCreator\", prompt:\"幫我建立一個網站：\"},\n  {t:\"開發應用\", ic:\"💻\", tool:\"MRL_SkillCreator\", prompt:\"幫我開發一個應用：\"},\n  {t:\"設計\",     ic:\"🎨\", tool:\"MRL_ImageStudio\", prompt:\"幫我設計：\"},\n  {t:\"Wide Research\", ic:\"🔎\", tool:\"MRL_WideResearch\", prompt:\"幫我深入研究：\"},\n];\n\n/* ── 後端探測 ── */\nlet CORE_ONLINE=false;\nasync function api(method,path,body){\n  const r=await fetch(path,{method,headers:{'content-type':'application/json'},body:body?JSON.stringify(body):undefined});\n  let data=null; try{data=await r.json()}catch(e){}\n  return {ok:r.ok,status:r.status,data};\n}\nasync function probe(){\n  try{\n    const r=await fetch('/api/mother/status');\n    // HTTP 200 但 available:false（母體未 boot）也視為未連線，不誤標「已連線」\n    if(r.ok){\n      let data=null; try{data=await r.json()}catch(e){}\n      CORE_ONLINE=(data&&data.available===false)?false:true;\n    }else{ CORE_ONLINE=false }\n  }catch(e){ CORE_ONLINE=false }\n  $('#coreDot').className='dot'+(CORE_ONLINE?'':' off');\n  $('#engineTag').textContent='engine: '+(CORE_ONLINE?'母體後端已連線':'前端模式（待接 DL580/MotherAssembly）');\n}\n\n/* ── Sessions (Issue #29) localStorage ── */\nconst DB={\n  load(){ try{return JSON.parse(localStorage.getItem('mrl_sessions')||'[]')}catch(e){return[]} },\n  save(s){ localStorage.setItem('mrl_sessions',JSON.stringify(s)) },\n};\nlet sessions=DB.load(), current=null;\nfunction newSession(){\n  const s={id:'MRL_'+Date.now().toString(36),label:'新會話',msgs:[],created:Date.now()};\n  sessions.unshift(s); DB.save(sessions); current=s.id; renderSessions(); openView('MRL_Dialogue');\n  return s;\n}\nfunction getCur(){ return sessions.find(s=>s.id===current) }\nfunction renderSessions(){\n  const el=$('#sesslist');\n  if(!sessions.length){ el.innerHTML='<div style=\"color:var(--dim);font-size:12px;padding:6px 10px\">尚無會話</div>'; return }\n  el.innerHTML='';\n  sessions.forEach(s=>{\n    const b=document.createElement('button'); b.className='sess'+(s.id===current?' on':'');\n    b.innerHTML=`<span>💬</span><span class=\"t\">${esc(s.label)}</span><span class=\"x\" title=\"刪除\">✕</span>`;\n    b.onclick=(e)=>{ if(e.target.classList.contains('x')){ delSession(s.id); e.stopPropagation(); return } current=s.id; renderSessions(); openView('MRL_Dialogue') };\n    el.appendChild(b);\n  });\n}\nfunction delSession(id){ sessions=sessions.filter(s=>s.id!==id); if(current===id)current=null; DB.save(sessions); renderSessions(); if(!current)openView('MRL_Dialogue') }\n\n/* ── Nav render ── */\nfunction renderNav(){\n  const tw=$('#navtools'), cw=$('#navcore'); tw.innerHTML=''; cw.innerHTML='';\n  TOOLS.forEach(t=>{\n    const b=document.createElement('button'); b.className='nav'; b.dataset.id=t.id;\n    b.innerHTML=`<span class=\"ic\">${t.ic}</span><span>${esc(t.name)}<small>${t.id}</small></span>`;\n    b.onclick=()=>openView(t.id);\n    (t.sec==='core'?cw:tw).appendChild(b);\n  });\n}\nfunction setActiveNav(id){ document.querySelectorAll('.nav').forEach(n=>n.classList.toggle('on',n.dataset.id===id)) }\n\n/* ── Views ── */\nlet activeTool='MRL_Dialogue';\nconst isMobile=()=>window.matchMedia('(max-width:820px)').matches;\nfunction toggleDrawer(open){\n  const aside=$('#aside'); if(!aside)return;\n  const o=(open===undefined)?!aside.classList.contains('open'):open;\n  aside.classList.toggle('open',o); $('#scrim').classList.toggle('on',o);\n}\nfunction openView(id){\n  activeTool=id; setActiveNav(id);\n  const t=TOOLS.find(x=>x.id===id)||{};\n  $('#topTitle').textContent=t.name||'MRL_AI';\n  if(isMobile())toggleDrawer(false);\n  const c=$('#content');\n  if(id==='MRL_Dialogue'){ return getCur()?renderChat():renderHome() }\n  if(id==='MRL_Monitor'){ return renderMonitor() }\n  if(id==='MRL_Console'){ return renderConsole() }\n  if(id==='MRL_Config'||id==='MRL_Settings'){ return renderSettings() }\n  return renderToolStub(t);\n}\nfunction renderHome(){\n  $('#content').innerHTML=`\n    <div class=\"home view on\">\n      <h2>MRL_AI 能幫你做什麼？</h2>\n      <div class=\"lead\">直接輸入你的問題或任務，母體會接手。origin_signature = MrLiouWord</div>\n      <div class=\"composer\">\n        <textarea id=\"homeInput\" placeholder=\"問任何問題，或交派一個任務…\"></textarea>\n        <div class=\"row\">\n          <select id=\"homeMode\"><option value=\"chat\">對話 / chat</option><option value=\"agent\">任務 / agent</option></select>\n          <button class=\"send\" id=\"homeSend\">送出 ▷</button>\n        </div>\n      </div>\n      <div class=\"cards\" id=\"qcards\"></div>\n    </div>`;\n  const cards=$('#qcards');\n  HOME_CARDS.forEach(c=>{\n    const d=document.createElement('button'); d.className='qcard';\n    d.innerHTML=`<span class=\"ic\">${c.ic}</span><div><b>${c.t}</b><div style=\"color:var(--dim);font-size:12px\">${c.tool}</div></div>`;\n    d.onclick=()=>{ $('#homeInput').value=c.prompt; $('#homeInput').focus() };\n    cards.appendChild(d);\n  });\n  $('#homeSend').onclick=()=>{ const v=$('#homeInput').value.trim(); if(!v)return; const s=getCur()||newSession(); s.label=v.slice(0,24); send(v) };\n  $('#homeInput').addEventListener('keydown',e=>{ if((e.metaKey||e.ctrlKey)&&e.key==='Enter')$('#homeSend').click() });\n}\nfunction renderChat(){\n  const s=getCur(); if(!s)return renderHome();\n  $('#content').innerHTML=`\n    <div class=\"chatwrap view on\">\n      <div class=\"msgs\" id=\"msgs\"></div>\n      <div class=\"composer bottom\">\n        <textarea id=\"chatInput\" placeholder=\"繼續對話… (⌘/Ctrl+Enter 送出)\" style=\"min-height:54px\"></textarea>\n        <div class=\"row\"><span style=\"color:var(--dim);font-size:12px\">${esc(s.id)}</span>\n          <button class=\"send\" id=\"chatSend\">送出 ▷</button></div>\n      </div>\n    </div>`;\n  paintMsgs();\n  $('#chatSend').onclick=()=>{ const v=$('#chatInput').value.trim(); if(v){$('#chatInput').value='';send(v)} };\n  $('#chatInput').addEventListener('keydown',e=>{ if((e.metaKey||e.ctrlKey)&&e.key==='Enter')$('#chatSend').click() });\n}\nfunction paintMsgs(){\n  const s=getCur(), m=$('#msgs'); if(!m)return; m.innerHTML='';\n  s.msgs.forEach(x=>{\n    const d=document.createElement('div'); d.className='msg '+(x.role==='user'?'me':'ai');\n    const st=x.status?`<div class=\"status\">任務狀態 <span class=\"s ${x.status}\">${x.status}</span>${x.engine?' · engine: '+esc(x.engine):''}</div>`:'';\n    d.innerHTML=`<div class=\"av\">${x.role==='user'?'你':'✦'}</div><div><div class=\"bub\">${esc(x.text)}</div>${st}</div>`;\n    m.appendChild(d);\n  });\n  m.scrollTop=m.scrollHeight;\n}\n/* ── unwrapReply: dig out a string from any nesting ── */\nfunction unwrapReply(data){\n  let d=data; let depth=0;\n  while(d&&typeof d==='object'&&depth<8){\n    if(typeof d.reply==='string') return d.reply;\n    if(typeof d.output==='string') return d.output;\n    if(typeof d.text==='string') return d.text;\n    if(typeof d.reply==='object') d=d.reply;\n    else if(typeof d.output==='object') d=d.output;\n    else break;\n    depth++;\n  }\n  return JSON.stringify(data,null,2);\n}\nasync function send(text){\n  const s=getCur()||newSession();\n  s.msgs.push({role:'user',text});\n  const ai={role:'assistant',text:'',status:'QUEUED'}; s.msgs.push(ai);\n  DB.save(sessions); if(activeTool!=='MRL_Dialogue')openView('MRL_Dialogue'); else renderChat();\n  ai.status='RUNNING'; paintMsgs();\n  try{\n    const r=await api('POST','/api/chat',{message:text,session_id:s.id});\n    if(r.ok && r.data && r.data.ok!==false){\n      ai.text = unwrapReply(r.data);\n      ai.engine = r.data.engine || r.data.route || r.data.via || (CORE_ONLINE?'母體後端':'平台');\n      ai.status='DONE';\n    }else if(r.ok && r.data && r.data.ok===false){\n      // 後端以 HTTP 200 回 {ok:false,reason}（如母體未 boot、message 缺漏）— 誠實標 FAILED\n      ai.status='FAILED';\n      const reason=(typeof r.data.reason==='string'&&r.data.reason.trim())?r.data.reason.trim():JSON.stringify(r.data,null,2);\n      ai.text='⚠ 母體回報失敗：'+reason;\n    }else{\n      ai.status='FAILED';\n      const reason=(r.data&&(r.data.reason||r.data.error))||('HTTP '+r.status);\n      ai.text='⚠ 母體後端尚未連通（'+reason+'）。\\n\\n'\n            +'此回應需要 MRL 母體後端 (MotherAssembly / DL580 runtime)。\\n'\n            +'本頁為對外產品入口；接上後端後即可真實對話，不偽造結果。\\n'\n            +'請在 Cloudflare 設 MRL_DL580_ORIGIN，或在本機啟動 MRL_Platform_Server.py。';\n    }\n  }catch(e){\n    ai.status='FAILED';\n    ai.text='⚠ 無法連線母體後端。本頁為前端入口（可獨立瀏覽）；\\n真實對話需啟動後端：python3 MRL_Platform_Server.py，或部署 DL580。';\n  }\n  DB.save(sessions); paintMsgs();\n}\nfunction renderMonitor(){\n  $('#content').innerHTML=`<div class=\"panel view on\"><h2>即時監控</h2><div class=\"lead\">MRL_Monitor · /api/monitor</div>\n    <div class=\"box\"><button class=\"act primary\" id=\"refMon\">刷新</button><pre id=\"monOut\">點「刷新」載入母體監控聚合…</pre></div></div>`;\n  $('#refMon').onclick=async()=>{ $('#monOut').textContent='查詢中…';\n    const r=await api('GET','/api/monitor'); $('#monOut').textContent=r.ok?JSON.stringify(r.data,null,2):needCore(r) };\n}\nfunction renderConsole(){\n  $('#content').innerHTML=`<div class=\"panel view on\"><h2>母體控制台</h2><div class=\"lead\">MRL_Console · MotherAssembly</div>\n    <div class=\"box\"><div class=\"kv\"><button class=\"act primary\" id=\"mstat\">母體狀態</button><button class=\"act\" id=\"dl580\">跑 DL580 管線</button></div>\n    <pre id=\"consoleOut\">母體狀態 / DL580 管線。動態功能需後端 (MotherAssembly / DL580)。</pre></div></div>`;\n  $('#mstat').onclick=async()=>{ $('#consoleOut').textContent='查詢中…'; const r=await api('GET','/api/mother/status'); $('#consoleOut').textContent=r.ok?JSON.stringify(r.data,null,2):needCore(r) };\n  $('#dl580').onclick=async()=>{ $('#consoleOut').textContent='跑管線中…'; const r=await api('POST','/api/dl580/run',{source:'平台觸發'}); $('#consoleOut').textContent=r.ok?JSON.stringify(r.data,null,2):needCore(r) };\n}\nfunction renderSettings(){\n  $('#content').innerHTML=`<div class=\"panel view on\"><h2>設定 · MRL Config</h2><div class=\"lead\">內部命名 (MRL_) ↔ 外部商業顯示名映射 · Issue #28</div>\n    <div class=\"box\"><table><thead><tr><th>內部 canonical (MRL_)</th><th>外部顯示名</th><th>分區</th></tr></thead><tbody>\n    ${TOOLS.map(t=>`<tr><td><code>${t.id}</code></td><td>${esc(t.name)}</td><td>${t.sec}</td></tr>`).join('')}\n    </tbody></table></div>\n    <div class=\"box\"><b>系統</b><pre>origin_signature: ${ORIGIN_SIGNATURE}\nsovereignty_mode: 權位區分模式\ncanonical_language: 中文（英文僅作 Adapter 對照）\ncore_backend: ${CORE_ONLINE?'已連線':'未連線（前端入口模式）'}</pre></div></div>`;\n}\nfunction renderToolStub(t){\n  $('#content').innerHTML=`<div class=\"panel view on\"><h2>${esc(t.name)}</h2><div class=\"lead\">${t.id} · MRL 工具模組</div>\n    <div class=\"banner\"><span>●</span><div><b>此工具的執行需母體後端</b><br>\n      ${esc(t.name)}（${t.id}）為產品入口已就位的工具項；其生成/執行能力由 MRL 母體後端 (MotherAssembly / DL580 runtime) 提供。<br>\n      目前後端：<b>${CORE_ONLINE?'已連線，可在「AI 對話」直接交派任務':'未連線（前端入口模式）'}</b>。不偽造輸出。</div></div>\n    <div class=\"box\"><textarea id=\"stubIn\" placeholder=\"輸入要交派給「${esc(t.name)}」的任務…\" style=\"width:100%;min-height:80px;background:var(--panel2);border:1px solid var(--line);border-radius:10px;color:var(--ink);padding:12px;font:inherit\"></textarea>\n    <div class=\"row\" style=\"display:flex;margin-top:10px\"><button class=\"act primary\" id=\"stubGo\" style=\"margin-left:auto\">交派任務 ▷</button></div></div></div>`;\n  $('#stubGo').onclick=()=>{ const v=$('#stubIn').value.trim(); if(!v)return; const s=getCur()||newSession(); s.label='['+t.name+'] '+v.slice(0,18); send('['+t.id+'] '+v) };\n}\nfunction needCore(r){ return '⚠ 需母體後端 (HTTP '+r.status+')。\\n'+((r.data&&r.data.reason)?('原因：'+r.data.reason):'啟動 MRL_Platform_Server.py 或設定 DL580 origin。') }\nfunction esc(s){ return String(s).replace(/[&<>\"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;'}[c])) }\n\n/* ── boot ── */\nfunction enter(){\n  $('#login').classList.add('hide'); $('#app').classList.remove('hide');\n  renderNav(); renderSessions();\n  if(!sessions.length) renderHome(); else { current=sessions[0].id; renderSessions(); }\n  openView('MRL_Dialogue');\n  if(isMobile())toggleDrawer(true);   // 手機進入先打開工具列，讓你看得到\n  probe(); setInterval(probe,15000);\n}\n$('#menuBtn').onclick=()=>toggleDrawer();\n$('#scrim').onclick=()=>toggleDrawer(false);\n$('#guest').onclick=enter;\n$('#magic').onclick=()=>alert('Email 登入連結需 MRL_Auth 後端（Issue #11 · P1-1）。\\n目前可用「以訪客進入」瀏覽完整產品入口。');\ndocument.querySelectorAll('[data-sso]').forEach(b=>b.onclick=()=>alert(b.dataset.sso+' 登入需 MRL_Auth 後端（P1-1），尚未接通。\\n請用「以訪客進入」。'));\n$('#newSess').onclick=()=>newSession();\n// 若已有會話，allow Enter on email to guest-enter for speed\n$('#email').addEventListener('keydown',e=>{ if(e.key==='Enter')enter() });\n</script>\n</body>\n</html>\n";
